@font-face{font-family:Plex;src:url('/assets/fonts/plexmono-400.woff2')}@font-face{font-family:Plex;src:url('/assets/fonts/plexmono-500.woff2');font-weight:500}@font-face{font-family:Plex;src:url('/assets/fonts/plexmono-600.woff2');font-weight:600}@font-face{font-family:Silk;src:url('/assets/fonts/silkscreen-400.woff2')}@import url('https://fonts.googleapis.com/css2?family=Silkscreen:wght@700&display=swap');
:root{font-family:Plex,monospace;color:#e5e6d7;background:#101513;font-synthesis:none;--cream:#e5e6d7;--muted:#8a9282;--orange:#d9784b;--green:#a6c58e;--line:rgba(222,224,204,.18)}*{box-sizing:border-box}html,body,#app{margin:0;width:100%;height:100%;overflow:hidden}body{font-size:11px;letter-spacing:.03em}#app{position:relative;background:#141d16}#world{position:absolute;inset:0;width:100%;height:100%;display:block;image-rendering:pixelated}.grain,.vignette,.scanlines{position:absolute;inset:0;pointer-events:none}.grain{z-index:3;opacity:.10;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.91' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E")}.vignette{z-index:2;background:radial-gradient(ellipse at 48% 47%,transparent 23%,rgba(5,11,8,.35) 70%,rgba(3,8,6,.83) 130%)}.scanlines{z-index:4;opacity:.08;background:repeating-linear-gradient(0deg,transparent 0px,transparent 2px,#000 3px,#000 4px);mix-blend-mode:multiply}.title-screen{position:absolute;z-index:5;inset:0;background:linear-gradient(90deg,rgba(8,14,10,.89) 0%,rgba(9,15,11,.75) 31%,rgba(9,15,11,.14) 75%,rgba(9,15,11,.18) 100%),linear-gradient(0deg,rgba(8,14,11,.7),transparent 30%,rgba(8,14,11,.2);transition:opacity .8s,visibility .8s}.title-screen.leaving{opacity:0;visibility:hidden}.topline{height:74px;padding:0 5.25%;display:flex;align-items:center;border-bottom:1px solid rgba(220,224,203,.13);gap:18px}.brand-mark{font:20px Silk;letter-spacing:-3px;color:#e9e9d8;display:flex;align-items:center}.brand-mark span,.loading-mark span{color:var(--orange);font-size:17px;margin-left:4px}.topline-text,.topline-right{font-size:9px;letter-spacing:.15em;color:#a6ad9e}.topline-right{margin-left:auto;color:#c5c6b7}.status-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c96d4c;margin-right:8px;box-shadow:0 0 10px #d9784b}.title-copy{position:absolute;left:11.2%;top:23.1%}.eyebrow{display:flex;align-items:center;color:#a5b39a;font-size:9px;letter-spacing:.16em}.eyebrow-line{height:1px;width:24px;background:var(--orange);margin-right:11px}.title-copy h1{font:clamp(72px,10vw,148px)/.79 Silk,monospace;letter-spacing:-.095em;margin:28px 0 21px;color:#e9e9d8;text-shadow:0 5px 36px #07100bb5}.title-copy h1 span{font-size:.46em;letter-spacing:.09em;color:#b9c9ad;display:inline-block;margin-top:12px}.title-rule{display:flex;align-items:center;gap:12px;width:min(378px,80vw);margin:31px 0 19px}.title-rule span{height:1px;background:rgba(221,224,201,.24);flex:1}.title-rule span:first-child{max-width:31px;background:var(--orange)}.title-rule small{font-size:9px;letter-spacing:.19em;color:#d9a084}.intro{font-size:12px;line-height:2;color:#b3b7aa;letter-spacing:.025em;margin:0}.menu-bottom{position:absolute;left:11.2%;bottom:9.4%;display:flex;align-items:flex-end;gap:clamp(35px,8vw,130px)}.play-button{height:53px;min-width:286px;padding:0 18px;border:1px solid rgba(215,120,75,.8);background:rgba(26,35,27,.73);color:#e9e8d6;display:flex;align-items:center;gap:15px;font:10px Plex;letter-spacing:.12em;cursor:pointer;transition:background .2s,border .2s,transform .2s}.play-button:hover{background:#d9784b;color:#101512;transform:translateY(-2px);border-color:#e29165}.play-glyph{font-size:11px;color:var(--orange)}.play-button:hover .play-glyph{color:#101512}.button-arrow{margin-left:auto;color:var(--orange);font-size:16px}.play-button:hover .button-arrow{color:#101512}.play-sub{margin-top:13px;font-size:8px;color:#969d8e;letter-spacing:.1em;white-space:nowrap}.keycap{color:#d9dacb;border-bottom:1px solid #777e70;padding-bottom:2px}.sub-divider{padding:0 9px;color:#596154}.mode-card{min-width:220px;padding-bottom:2px}.mode-label{font-size:8px;letter-spacing:.17em;color:#8a9282;margin-bottom:12px}.mode-options{display:flex;gap:17px}.mode-option{padding:0;border:0;ba