  if(p.state==='wander'&&pos.distanceTo(new THREE.Vector3(p.target.x,heightAt(p.target.x,p.target.z),p.target.z))<3){p.target.set((rand()-.5)*140,0,(rand()-.5)*140);}
  if((p.state==='investigate'||p.state==='search')&&pos.distanceTo(p.target)<2.8){if(p.state==='investigate'){p.state='search';p.searchUntil=elapsed+5;}else if(elapsed>(p.searchUntil||0))p.state='wander';else p.target.set(p.target.x+(rand()-.5)*8,0,p.target.z+(rand()-.5)*8);}
  const heardRecently=elapsed-p.lastHeard<9;
  if(distance<closestD){closestD=distance;closest=p;}
  if(p.state==='charge'&&distance>34&&!heardRecently)p.state='investigate';
  let goal=p.target,speed=p.speed*(p.state==='wander'?.24:p.state==='search'?.42:p.state==='investigate'?.72:1);
  if(p.state==='charge'){goal=player.position;}
  const dir=new THREE.Vector3(goal.x-pos.x,0,goal.z-pos.z);if(dir.lengthSq()>.05){dir.normalize();const desiredYaw=Math.atan2(dir.x,dir.z);let delta=((desiredYaw-p.group.rotation.y+Math.PI*3)%(Math.PI*2))-Math.PI;p.group.rotation.y+=clamp(delta,-p.turn*dt,p.turn*dt);pos.x+=Math.sin(p.group.rotation.y)*speed*dt;pos.z+=Math.cos(p.group.rotation.y)*speed*dt;}
  pos.x=clamp(pos.x,-97,97);pos.z=clamp(pos.z,-97,97);pos.y=heightAt(pos.x,pos.z);p.group.userData.phase+=dt*(p.state==='charge'?13:5);p.group.userData.rig.position.y=Math.abs(Math.sin(p.group.userData.phase))*.12;
  if(distance<1.8&&p.attackCooldown<=0){p.attackCooldown=2.1;health-=p.kind==='mossman'?34:27;$('#status-text').textContent='WOUNDED';tell(p.kind==='mossman'?'MOSS-01 IMPACT — IT FOLLOWED THE LAST STEP.':'XENON CONTACT — THE HANDS ARE CLOSE.',2100);lastAttack=elapsed;if(health<=0){health=0;dead=true;setTimeout(respawn,1800);}}
 }
 if(closestD<32&&closestD<closest.hear*(noise+.55)){
  $('#threat').classList.remove('hidden');$('#threat-name').textContent=closest.name==='MOSSMAN'?'MOSS-01 HEARD YOU':'WARDEN IS LISTENING';$('#threat-distance').textContent=`${closest.state==='charge'?'CLOSING':'SOUND TRACE'} — ${Math.round(closestD)} M`;
 }else $('#threat').classList.add('hidden');
 // The survivor echoes retreat from predators and move between cover instead of following the player.
 bots.forEach((bot,i)=>{
  const bpos=bot.group.position;let danger=null,dd=1e9;for(const p of predators){const d=bpos.distanceTo(p.group.position);if(d<dd){dd=d;danger=p;}}
  if(dd<28){const away=new THREE.Vector3(bpos.x-danger.group.position.x,0,bpos.z-danger.group.position.z).normalize();bot.goal.set(bpos.x+away.x*(25+rand()*12),0,bpos.z+away.z*(25+rand()*12));bot.alert=2.5;}
  else if(bot.alert<=0&&bpos.distanceTo(bot.goal)<3){bot.goal.set((rand()-.5)*150,0,(rand()-.5)*150);bot.alert=rand()*2;}
  bot.alert-=dt;const v=new THREE.Vector3(bot.goal.x-bpos.x,0,bot.goal.z-bpos.z);if(v.length()>1){v.normalize();bpos.x+=v.x*1.6*dt;bpos.z+=v.z*1.6*dt;bot.group.rotation.y=Math.atan2(v.x,v.z);bot.phase+=dt*5;bot.rig.position.y=Math.sin(bot.phase)*.12;}
  bpos.x=clamp(bpos.x,-96,96);bpos.z=clamp(bpos.z,-96,96);bpos.y=heightAt(bpos.x,bpos.z);
 });
}
function respawn(){if(!started)return;player.position.set(0,heightAt(0,0),0);velocity.set(0,0,0);health=62;stamina=65;dead=false;predators.forEach((p,i)=>{p.state='investigate';p.target.set(player.position.x+(i?18:-20),0,player.position.z+(i?18:-18));p.lastHeard=elapsed;});tell('YOU WAKE UNDER THE SAME CANOPY. KEEP MOVING.',3500);}

